      "name": "Oilskin Pouch",
      "itemType": "container",
      "level": 0,
      "rarity": "common",
      "traits": [],
      "description": "Treated with oil and animal fats, the leather of this pouch is more resistant to water but is also stiffer. Many makers and travelers decorate their oilskin pouches with symbols of the ocean and sailing. Often used to store scrolls or other paper documents when a traveler knows they will be in an area of heavy rain or near water. While not entirely waterproof, an oilskin pouch seals with sturdy leather ties, allowing it to resist anything other than total submersion. Even completely underwater, it will protect its contents for up to 1 minute.\nAn oilskin pouch can protect up to 1 Bulk of items.",
      "bulk": 0.1,
      "price": {
        "sp": 5
      },
      "usage": "worn",
