      "traits": [
        "catalyst",
        "consumable",
        "magical"
      ],
      "description": "Activate Cast a Spell (add 1 action)\nThe baubles wemmuths use to lure victims to their hunting grounds are dangerous to retrieve and often stained by blood. One of these trinkets covers the plant matter created by Entangling Flora with blood-drinking thorns. Creatures who fail or critically fail their Reflex saves against entangling flora also take piercing damage equal to the spell's rank.\nEffect: Wemmuth Trinket",
