      "level": 4,
      "rarity": "common",
      "traits": [
        "alchemical",
        "consumable",
        "injury",
        "poison"
      ],
      "description": "Activate 2 (manipulate)\nThis poison is extracted carefully from a mandragora's thorny vines in a process that, due to the mandragora's humanoid form, eerily mirrors drawing blood.\nSaving Throw check (fortitude, dc:21)\nMaximum Duration 6 rounds\nStage 1 1d6 poison damage and Stupefied 1 (1 round)\nStage 2 1d6 poison damage, Confused, and stupefied 1 (1 round)\nStage 3 2d6 poison damage, confused, and stupefied 1 (1 round)",
