      "description": "You have a strong, prehensile tail. You gain a tail unarmed attack that deals 1d6 bludgeoning damage. This tail is in the brawling group. You gain a +1 item bonus to Acrobatics checks to Balance and to Athletics checks to Climb. You can also use your tail for the Grab an Edge action, even if your hands are otherwise occupied.\nYou can use your tail unarmed attack to Grapple even if you don't have a free hand. You gain a +2 item bonus to Athletics checks to Grapple.",
