      "traits": [
        "catalyst",
        "consumable",
        "magical"
      ],
      "description": "Activate Cast a Spell\nThe pelt of a witchwarg stays cold long after it leaves the creature's body. A tuft of this fur can freeze a Fire Shield spell into solid ice, inverting its usual effects. The spell's fire trait is replaced with the cold trait, you gain resistance to fire damage and environmental heat effects (instead of cold effects), the shield is immune to cold damage instead of fire damage, and its Hardness is halved against fire effects. The damage you deal to creatures that touch you or hit you with a melee or unarmed attack has its type changed to cold.",
