    "translatableHash": "sha256:5e2c6af01f49aa44eaa613945fa4a4697148dcc26a6293367ee0ded2a9d48831",
    "data": {
      "schemaVersion": 1,
      "name": "Alluring Lantern",
      "itemType": "equipment",
      "level": 8,
      "rarity": "common",
      "traits": [
        "graft",
        "invested",
        "magical"
      ],
      "description": "An antenna with a bioluminescent lure protrudes from your head, drawing enemies' attention. When not activated, the antenna lays flat and blends in with your hair or skin.\nActivate—Raise Lure 1 (manipulate, mental, visual)\nFrequency once per day\nEffect Until the beginning of your next turn, the lure raises above your head and lights up with multicolored flashes that draws creatures closer. Any creature that begins its turn within 20-foot emanation of you must succeed at a check (will, dc:23, traits:mental,visual) save or become Fascinated by the lure and must spend at least one of its actions to move toward you. The fascination ends at the end of the creature's turn.",
      "bulk": 0.1,
      "price": {
        "gp": 450
      },
      "usage": "implanted",
      "category": "equipment",
      "group": "equipment"
    }
