      "traits": [
        "invested",
        "magical"
      ],
      "description": "This long hide cloak is stitched with patches of the ebony hair of a tikbalang. While wearing this cloak, you take a –2 item penalty to saves against illusions but gain a +2 item bonus to Deception checks.\nActivate—Illusory Thrash 2 (concentrate, illusion, manipulate, mental)\nFrequency once per day\nEffect You wrap the mantle around your body, causing you to briefly appear much larger than you are. Make a melee Strike. This Strike deals an additional 4d6 mental damage.\nCraft Requirements The initial raw materials must include the hide of a tikbalang.",
