      "name": "Camouflaging Chromatophores (Greater)",
      "itemType": "equipment",
      "level": 9,
      "rarity": "uncommon",
      "traits": [
        "graft",
        "invested",
        "magical"
      ],
      "description": "Special cells in your skin can change color to help you blend in with your environment. You gain a +2 item bonus to Stealth checks to Sneak and Hide.\nActivate—Background Adaptation 2 (concentrate)\nFrequency once per hour\nEffect For 1 minute, you can Hide without needing cover or concealment to do so. This doesn't allow you to Sneak without ending your movement in cover or concealment, however, as your skin's attempts to match the background as you move produce noticeable rippling waves of color.",
