    "translatableHash": "sha256:fdffe9cb198c8cf445270aef76a0ebb84381d1e5ebb92392bce419d30aab0fcd",
    "data": {
      "schemaVersion": 1,
      "name": "Hippopotamus Klar",
      "itemType": "shield",
      "level": 10,
      "rarity": "uncommon",
      "traits": [
        "integrated-1d6-s-versatile-p",
        "invested",
        "magical"
      ],
      "description": "This +1 striking klar is fashioned from the skull of a hippopotamus, with one of its canines acting as the blade. While wielding a hippopotamus klar, you gain a +1 item bonus to Intimidation checks.\nActivate—Engulfing Jaws 1 (manipulate)\nFrequency once per day\nEffect The hippo jaws of the shield open impossibly wide. Make a melee Strike with the klar blade targeting two creatures adjacent to each other. Roll the attack and damage once and apply it to each creature separately. This counts as two attacks for your multiple attack penalty.\nCraft Requirements The initial raw materials must include the entire skull of a hippopotamus.",
      "bulk": 1,
      "price": {
        "gp": 1000
      },
      "usage": "",
      "category": "shield",
      "group": "klar"
    }
