      "level": 2,
      "rarity": "common",
      "traits": [
        "invested",
        "magical"
      ],
      "description": "Squires with aspirations of being knights wear these loose, colorful tunics, typically emblazoned with the crest of the knight or kingdom they serve.\nActivate—At Your Aid 1 (concentrate)\nFrequency once per day\nEffect You race to the side of an ally who needs your help. You Stride twice, ignoring difficult terrain, but your movement must end adjacent to an ally.",
      "bulk": 0.1,
      "price": {
        "gp": 25
      },
      "usage": "worngarment",
