      "rarity": "common",
      "traits": [
        "invested",
        "magical"
      ],
      "description": "You keep yourself protected from incoming projectiles with this sturdy steel helmet, painted brown.\nActivate—Block Manipulation r (concentrate)\nFrequency once per day\nTrigger You gain the Stupefied condition\nEffect Your trusty helmet protects not only your head but your mind. The value of your stupefied condition is decreased by 1.\nActivate—Hunker Down 1 (manipulate)\nEffect You hunker down, protecting your head using your helmet. You gain a +1 circumstance bonus to your AC against ranged attacks.",
      "bulk": 0.1,
