      "name": "Siege Shield",
      "itemType": "shield",
      "level": 3,
      "rarity": "uncommon",
      "traits": [
        "magical"
      ],
      "description": "This massive tower shield (Hardness 5, HP 20, BT 10) is crafted from the toughest steel. It's not ideal for single combat, but it can be used to defend soldiers during a siege. While this shield is raised, you gain resistance to damage from siege weapons equal to half this shield's Hardness.\nActivate—Plant Cover 1 (manipulate) You unequip the shield and prop it on the ground. The shield grants standard cover for one Medium or smaller creature in its square and lesser cover for a Large one.",
