      "rarity": "common",
      "traits": [
        "invested",
        "magical"
      ],
      "description": "A good pair of gloves is a critical item for any soldier, particularly if you plan to get up close to your enemy. When you wear these black leather gloves with fine silver stitching, you gain a +1 item bonus to Athletics checks to Climb, Grapple, and Reposition.\nActivate—Sticky Grip 1 (manipulate)\nFrequency once per day\nRequirements You have an enemy Grabbed or Restrained\nEffect Your gloves help you squeeze even more tightly, keeping your opponent from moving freely. The enemy you have grabbed or restrained is Slowed 1 for 1 round.",
