      "traits": [
        "air",
        "invested",
        "magical"
      ],
      "description": "This black canvas mask covers your mouth and nose, with thick tubes coming from the sides. While wearing this mask, you gain a +1 item bonus to saves against inhaled poisons, inhaled diseases, and olfactory effects.\nActivate—Breathe Clean 1 (manipulate)\nFrequency once per day\nEffect Your mask springs to life, pumping clean air into your nose and mouth. For 1 round, you are immune to inhaled poisons, inhaled diseases, and olfactory effects. If you have ongoing effects due to such an effect from before activating the mask, those effects continue as normal. If the air around you is unbreathable, you are underwater, or you are in a vacuum, you can breathe normally.",
