      "rarity": "common",
      "traits": [
        "consumable",
        "magical",
        "whetstone"
      ],
      "description": "Activate 1 (manipulate)\nThis thick lead disk is etched with geometric patterns, and a weapon it's applied to grows unusually heavy. When you attack with a weapon under the effects of a mighty counterweight, you deal an amount of additional bludgeoning damage equal to the number of weapon damage dice.\nEffect: Mighty Counterweight",
