      "description": "Ammunition any\nActivate 1 (manipulate)\nEtched with the symbol of a ram's head, activated battering ammunition magically gathers momentum as it flies, imparting this momentum to its target on a successful Strike. It deals bludgeoning damage instead of its normal damage type and pushes the target 5 feet on a successful hit.",
      "bulk": 0.1,
