      "description": "This magical banner shimmers in a fiery array of reds, oranges, and yellows. The rampant threads catch light in the wind and give the appearance of a blazing flame. Whenever you or an ally within the banner's aura critically succeeds with a Strike, the Strike deals an additional 1d4 persistent fire damage.",
