      "level": 5,
      "rarity": "common",
      "traits": [
        "consumable",
        "magical",
        "whetstone"
      ],
      "description": "Activate 1 (manipulate)\nThis jagged bit of metal is pitted and worn but wickedly sharp. The DC of the flat check to end persistent bleed damage dealt by a weapon under the effects of a toothy knife is 17 (or 12 with appropriate assistance). This bleeding still typically ends on its own after 1 minute, as normal.\nEffect: Toothy Knife",
