      "traits": [
        "invested",
        "magical"
      ],
      "description": "This +1 leather armor has two medium-sized pockets just above the waist where you might normally place your hands if they were cold. Each pocket is covered with a leather flap that surprisingly remains closed even with dynamic movement and heavy winds. Each individual pocket functions as a Spacious Pouch (Type I).\nCraft Requirements The initial raw materials must include two type I spacious pouches.",
