      "level": 7,
      "rarity": "common",
      "traits": [
        "consumable",
        "magical",
        "whetstone"
      ],
      "description": "Activate 1 (manipulate)\nThis crescent-shaped shard of iridescent metal is strangely translucent, fading to a blurry outline when examined for too long. A weapon under the effects of a greater ethereal crescent gains the effects of an Astral rune for 1 minute. This does not count against the weapon's normal maximum number of runes.\nEffect: Ethereal Crescent",
