      "rarity": "common",
      "traits": [
        "consumable",
        "magical"
      ],
      "description": "Ammunition arrow, bolt\nActivate 1 (manipulate)\nThese arrows have tips grooved like a drill bit and angled fletching, causing them to spin quickly about their shaft when fired. When striking a structure or object of Hardness 14 or less within your first range increment, an activated burrowing bolt tunnels into the surface silently and leaves a hole behind it, burrowing through up to 5 feet of material before magically vanishing.",
