      "level": 7,
      "rarity": "uncommon",
      "traits": [
        "invested",
        "magical"
      ],
      "description": "This +1 leather armor has interlocking panels and short bristles along the outer edges of the arms and legs. While wearing this armor, you gain resistance 2 to acid damage.\nActivate—Dig 1 (manipulate)\nFrequency once per day\nEffect The bristles along your limbs enable you to tunnel through dirt and sand. For 1 minute, you gain a burrow Speed equal to half your land Speed.\nEffect: Ankhrav Carapace",
