    "translatableHash": "sha256:2c9dacec04764708c99686ccba6c2ff43314c67fe1b4d7871631f977c65df8a7",
    "data": {
      "schemaVersion": 1,
      "name": "Watcher's Armband",
      "itemType": "equipment",
      "level": 8,
      "rarity": "uncommon",
      "traits": [
        "detection",
        "invested",
        "magical"
      ],
      "description": "Soldiers who wear this burgundy armband serve as law enforcement within the ranks of a nation's military, seeking out those who would commit crimes while in uniform. While wearing the armband, you gain a +2 item bonus to your Perception DC against Deception checks to Lie to you. In addition, you can cast Ring of Truth once per day as an innate 3rd-rank occult spell.\nActivate—Find the Plant 1 (concentrate, detection, manipulate)\nFrequency once per day\nEffect Sometimes people aren't in control of their minds. You activate your armband, which, for the next minute, suddenly glows red if anyone within 30 feet of you is under the effect of a magical mental effect that is controlling their mind or body (such as Dominate).",
      "bulk": 0,
      "price": {
        "gp": 500
      },
      "usage": "wornarmbands",
      "category": "equipment",
      "group": "equipment"
    }
