      "rarity": "uncommon",
      "traits": [
        "magical"
      ],
      "description": "This minor reinforced buckler (Hardness 6, HP 50, BT 25) is a lightweight metal disk with a rounded bump at the center. The shield gives off a light hum near magic.\nActivate—Spell Amp 1 (manipulate)\nFrequency once per day\nEffect You throw your shield up to 30 feet into an unoccupied space you can see. The shield magically floats in the space as a focal point for your magic for 1 minute. You can cast spells using the shield as your point of origin, calculating range and cover from its space instead of yours. You can Dismiss this effect, causing the shield to fly back to your hand. If the shield breaks, the effect ends.",
