      "rarity": "common",
      "traits": [
        "invested",
        "magical"
      ],
      "description": "This +1 half plate is imbued with a series of runes designed to amplify your voice on the battlefield. You are more readily able to command and motivate the troops, even over the din of battle.\nActivate—Motivate 1 (concentrate, manipulate)\nFrequency once per hour\nEffect For 1 minute, the volume of your voice is temporarily enhanced, and you gain a +1 status bonus to Diplomacy and Intimidation checks.\nEffect: Command Cuirass",
