      "name": "Banner of Creeping Death (Moderate)",
      "itemType": "equipment",
      "level": 9,
      "rarity": "uncommon",
      "traits": [
        "aura",
        "magical"
      ],
      "description": "The very fabric of this off-putting magical banner seems to be rotting with a slick, foul texture. Traditionally, these banners were created from the uniforms of fallen enemy troops, but this is considered a cruel and dishonorable practice by many modern nations. While holding a banner of creeping death, you can use the following ability.\nActivate—Void's Embrace 1 (concentrate, void)\nFrequency once per minute\nEffect A massive wave of void energy floods out from the banner in all directions. All living creatures within the banner's aura take 2d4+2 void damage (check (fortitude, basic, dc:26, options:area-effect, traits:concentrate,void) save).",
