      "name": "Sailor's Collar (Greater)",
      "itemType": "equipment",
      "level": 10,
      "rarity": "common",
      "traits": [
        "invested",
        "magical"
      ],
      "description": "Veteran sailors like to wear this jaunty blue collar, tied with a small bow in the front and tucked into the belt. It can even save your life if you fall overboard. When wearing the sailor's collar, you gain a +2 item bonus to Athletics checks.\nActivate—Gasp for Air r (air, concentrate)\nFrequency once per day\nTrigger You fail a Swim check\nEffect Your collar inflates, giving you something to breathe from. You can breathe underwater, and you gain a 10-foot swim Speed for 1 minute.\nEffect: Gasp for Air",
