      "name": "Swift Standard",
      "itemType": "equipment",
      "level": 12,
      "rarity": "rare",
      "traits": [
        "air",
        "aura",
        "magical"
      ],
      "description": "As this magical banner sways in the breeze, the horses embroidered across the fabric seem to gallop at unnatural speeds, racing across the field. You and allies that start your turn within the banner's aura gain a +5-foot status bonus to land Speeds for 1 round. This bonus is doubled while traveling.\nEffect: Swift Standard",
