      "traits": [
        "fatal-d10",
        "magical"
      ],
      "description": "The head of this +2 striking pick is adorned with a detailed etching of an eagle with outstretched wings. When you use it to Strike an unattended object whose intended purpose is to restrain or confine, such as a pair of manacles or the bars of a prison cell, you ignore the first 10 points of the object's Hardness.\nActivate—Liberating Strike 2\nFrequency once per day\nEffect You Strike a creature with the chainbreaker. If you hit and deal damage, one Grabbed or Restrained ally within 60 feet of the target can use a reaction to attempt to Escape.",
