      "level": 12,
      "rarity": "common",
      "traits": [
        "magical"
      ],
      "description": "This brass horn is marked by age but remains in excellent condition. The rim of the mouth is ringed by finely carved runes. This bugle grants you a +2 item bonus to Performance checks while playing music with the instrument.\nActivate—Reveille 1 (auditory, manipulate)\nFrequency once per day\nEffect You blow a swift cadence of sharp notes that carries through the air. You and all allies within a 30-foot type:emanation can immediately Stand as a free action; this doesn't provoke reactions.",
