      "traits": [
        "aura",
        "light",
        "magical"
      ],
      "description": "The warm, caring light of the sun glows from the center of this magical banner, mirroring the dawn. This magical banner exudes bright light in the banner's aura (and dim light in an area equal to twice the banner's aura). This effect is suppressed when you aren't holding the banner or wielding the weapon it is affixed to.\nThis magical banner also grants a +1 status bonus to saving throws against unholy effects to all creatures within the banner's aura.",
