    "sourceHash": "sha256:2d53664c180d385e98b9b84310c1117bee24db5dabf8aa1c4619f5f588fc8772",
    "translatableHash": "sha256:4e27141bc9808f03f21bbe4c398818ab0e679c698ec9af3def7b47cbd67517ff",
