      "name": "Fireproof Gloves (Greater)",
      "itemType": "equipment",
      "level": 13,
      "rarity": "common",
      "traits": [
        "invested",
        "magical"
      ],
      "description": "First developed by blacksmiths to move burning hot workpieces around, fireproof gloves then became popular with soldiers responsible for disabling bombs and magical traps. The thick tan gloves come up over the arm. When wearing these gloves, you gain fire resistance 10.\nActivate—Release Heat 1 (concentrate, fire)\nFrequency once per day\nRequirements You have a free hand\nEffect You take the heat that's built up in your gloves and discharge it onto an enemy. You deal 10d8 fire damage to one creature within reach (check (reflex, dc:31, basic, traits:concentrate,fire) save).",
      "bulk": 0.1,
      "price": {
        "gp": 2500
      },
      "usage": "worngloves",
