      "name": "Frost Furs",
      "itemType": "armor",
      "level": 14,
      "rarity": "uncommon",
      "traits": [
        "cold",
        "invested",
        "magical"
      ],
      "description": "This fur-lined +2 greater resilient cold-resistant hide armor is favored by warriors in the Crown of the World. In addition to providing excellent protection from extreme elements, the armor also enables you to erect massive walls of ice.\nActivate—Endure 3 (concentration, manipulate, primal)\nFrequency once per day\nEffect You cast 5th-rank Environmental Endurance on yourself.\nActivate—Freeze Enemy 3 (cold, concentration, manipulate, primal)\nFrequency once per day\nEffect You cast Wall of Ice.\nCraft Requirements Supply a casting of environmental endurance (5th rank) and wall of ice.",
