      "rarity": "common",
      "traits": [
        "consumable",
        "magical",
        "whetstone"
      ],
      "description": "Activate 1 (manipulate)\nContained within this small iron-bound glass sphere is a raging whirlwind of colors, each fighting for prominence. After a successful Strike with a weapon enhanced by frenzied quintessence, you are Quickened for 1 round. You can use the additional action only to Stride toward a foe or Strike.",
