      "traits": [
        "magical"
      ],
      "description": "This minor reinforcing steel shield (Hardness 8, HP 64, BT 32) is lined with pale silver that glows when struck. Whenever you use the Shield Block reaction, this shield becomes energized for 1 round.\nActivate—Energized Blast 1 (force, manipulate)\nFrequency once per 10 minutes\nRequirements The shield is energized\nEffect You direct the stored energy into a short blast, targeting a creature within 15 feet. The target takes 4d10 force damage (check (reflex, dc:34, basic) save).",
