      "rarity": "uncommon",
      "traits": [
        "invested",
        "magical"
      ],
      "description": "Elite archers can go through countless arrows over the course of a battle. Smart ones carry an endless quiver to ensure they never run out. This quiver holds 100 mundane arrows and regenerates 10 per hour. Once an arrow is removed from the endless quiver, it dissipates after 1 minute.\nActivate—Convert Arrows 1 (manipulate)\nFrequency once per day\nEffect You tap the quiver, and the arrows inside transform into adamantine, dawnsilver, cold iron, or silver. They revert to wood after 1 minute.\nEffect: Convert Arrows",
