      "description": "This bright-red +3 greater resilient full plate is adorned with eerily beautiful, angry flames that flow and glow with your movement, making it appear as if you are engulfed in a living fire. You gain resistance 10 to fire while wearing this armor.\nActivate—Living Flame 2 (aura, concentrate, fire)\nFrequency once per day\nEffect The armor engulfs you in a vortex of living fire in a 15-foot type:emanation for 10 minutes. Creatures that enter this aura or start their turn within it take 10d6 fire damage (check (reflex, dc:40, basic, options:area-effect, traits:aura,concentrate,fire) save). This area is difficult terrain for other creatures.",
